{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.cluster_category_meta_v2 AS WITH unique_pincode_mapping AS ( SELECT PINCODE, STATENAME, ROW_NUMBER() OVER (PARTITION BY PINCODE ORDER BY STATENAME) AS rn FROM snitch_db.maplemonk.PINCODE_DISTRICT_MAPPING ), pincode_mapping AS ( SELECT a.PINCODE, UPPER(a.SKU) AS SKU, COALESCE(a.SHIPPING_QUANTITY + a.RETURN_QUANTITY + a.CANCELLED_QUANTITY, 0) AS ONLINE_SALES, b.STATENAME FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_SNITCH AS a LEFT JOIN unique_pincode_mapping AS b ON CAST(a.PINCODE AS VARCHAR) = CAST(b.PINCODE AS VARCHAR) WHERE b.rn = 1 ), online_mapping AS ( SELECT UPPER(b.SKU) AS SKU, UPPER(b.SKU_GROUP) AS SKU_GROUP, ROW_NUMBER() OVER (PARTITION BY b.SKU ORDER BY b.SKU_GROUP ASC) AS rn FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_SNITCH b ), online_skugrp_mapping AS ( SELECT s.STATENAME AS STATE, SUM(s.ONLINE_SALES) AS ONLINE_SALES, r.SKU_GROUP FROM pincode_mapping s LEFT JOIN online_mapping r ON s.SKU = r.SKU WHERE r.rn = 1 GROUP BY s.statename, r.SKU_GROUP ), online_category_mapping AS ( SELECT UPPER(SKU_GROUP) AS SKU_GROUP, UPPER(CATEGORY) AS CATEGORY FROM ( SELECT UPPER (SKU_GROUP) AS SKU_GROUP, UPPER(CATEGORY) AS CATEGORY, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY UPPER(CATEGORY) ASC) AS rn FROM snitch_db.maplemonk.CATEGORY_JOURNEY ) ranked WHERE rn = 1 ), online_data AS ( SELECT sm.ONLINE_SALES AS ONLINE_SALES, sm.SKU_GROUP AS SKU_GROUP, sm.STATE AS STATE, cm.CATEGORY AS CATEGORY FROM online_skugrp_mapping sm LEFT JOIN ONLINE_CATEGORY_MAPPING cm ON sm.SKU_GROUP = cm.SKU_GROUP ), unique_branch_mapping AS ( SELECT a.\"STORE CODE\" AS BRANCH_CODE, UPPER(a.\"END BILLING\") AS STATE, ROW_NUMBER() OVER (PARTITION BY a.\"STORE CODE\" ORDER BY UPPER(a.\"END BILLING\")) AS rn FROM snitch_db.maplemonk.master_file AS a ), branch_mapping AS ( SELECT a.BRANCH_CODE, UPPER(a.SKU) AS SKU, COALESCE(a.SHIPPING_QUANTITY + a.RETURN_QUANTITY + a.CANCELLED_QUANTITY, 0) AS OFFLINE_SALES, b.STATE AS STATE FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE AS a LEFT JOIN unique_branch_mapping AS b ON b.BRANCH_CODE = a.BRANCH_CODE WHERE b.rn = 1 ), offline_mapping AS ( SELECT UPPER(b.SKU) AS SKU, UPPER(b.SKU_GROUP) AS SKU_GROUP, ROW_NUMBER() OVER (PARTITION BY b.SKU ORDER BY UPPER(b.SKU_GROUP) ASC) AS rn FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE b ), offline_skugrp_mapping AS ( SELECT s.STATE AS STATE, SUM(s.OFFLINE_SALES) AS OFFLINE_SALES, r.SKU_GROUP FROM branch_mapping s LEFT JOIN offline_mapping r ON s.SKU = r.SKU WHERE r.rn = 1 GROUP BY s.STATE, r.SKU_GROUP ), OFFLINE_CATEGORY_MAPPING AS ( SELECT SKU_GROUP, UPPER(CATEGORY) AS CATEGORY FROM ( SELECT SKU_GROUP, UPPER(CATEGORY) AS CATEGORY, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY UPPER(CATEGORY) ASC) AS rn FROM snitch_db.maplemonk.CATEGORY_JOURNEY ) ranked WHERE rn = 1 ), offline_data AS ( SELECT sm.OFFLINE_SALES AS OFFLINE_SALES, sm.SKU_GROUP AS SKU_GROUP, sm.STATE AS STATE, cm.CATEGORY AS CATEGORY FROM offline_skugrp_mapping sm LEFT JOIN OFFLINE_CATEGORY_MAPPING cm ON sm.SKU_GROUP = cm.SKU_GROUP WHERE cm.CATEGORY IS NOT NULL ), merged_sales as ( select COALESCE(od.SKU_GROUP, onl.SKU_GROUP) AS SKU_GROUP, COALESCE(od.STATE, onl.STATE) AS STATE, COALESCE(od.CATEGORY, onl.CATEGORY) AS CATEGORY, COALESCE(onl.ONLINE_SALES, 0)*0.3 + COALESCE(od.OFFLINE_SALES, 0)* 0.7 AS SALES FROM offline_data od FULL OUTER JOIN online_data onl ON od.SKU_GROUP = onl.SKU_GROUP AND od.STATE = onl.STATE ), METAFIELDS_MAPPING AS ( SELECT ms.SALES, ms.SKU_GROUP, ms.STATE AS STATE, ms.CATEGORY, UPPER(md.COLLAR) AS COLLAR, UPPER(md.DESIGNS) AS DESIGN, UPPER(md.FIT) AS FIT, UPPER(md.MATERIAL) AS MATERIAL, UPPER(md.SLEEVE_TYPE) AS SLEEVE, UPPER(md.STYLE) AS STYLE FROM merged_sales ms LEFT JOIN METAFIELDS_DATA md ON UPPER(ms.SKU_GROUP) = UPPER(md.SKU_GROUP) ), COLLAR_SALES AS ( SELECT a.CATEGORY, a.STATE, a.COLLAR, SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY, a.COLLAR) / NULLIF(SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY),0) AS COLLAR_SALES FROM METAFIELDS_MAPPING a ), DESIGN_SALES AS ( SELECT a.CATEGORY, a.STATE, a.DESIGN, SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY, a.DESIGN) / NULLIF(SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY),0) AS DESIGN_SALES FROM METAFIELDS_MAPPING a ), FIT_SALES AS ( SELECT a.CATEGORY, a.STATE, a.FIT, SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY, a.FIT) / NULLIF(SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY),0) AS FIT_SALES FROM METAFIELDS_MAPPING a ), SLEEVE_SALES AS ( SELECT a.CATEGORY, a.STATE, a.SLEEVE, SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY, a.SLEEVE) / NULLIF(SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY),0) AS SLEEVE_SALES FROM METAFIELDS_MAPPING a ), MATERIAL_SALES AS ( SELECT a.CATEGORY, a.STATE, a.MATERIAL, SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY, a.MATERIAL) / NULLIF(SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY),0) AS MATERIAL_SALES FROM METAFIELDS_MAPPING a ), STYLE_SALES AS ( SELECT a.CATEGORY, a.STATE, a.STYLE, SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY, a.STYLE) / NULLIF(SUM(a.SALES) OVER (PARTITION BY a.STATE, a.CATEGORY),0) AS STYLE_SALES FROM METAFIELDS_MAPPING a ), category_specific_metafields AS ( SELECT \'SHIRTS\' AS CATEGORY, m.STATE, NULL AS COLLAR, m.DESIGN, NULL AS FIT, NULL AS MATERIAL, m.SLEEVE, NULL AS STYLE, (0.5 * COALESCE(MAX(b.design_sales), 0)) + (0.5 * COALESCE(MAX(e.sleeve_sales), 0)) AS RAW_SALES_PERC FROM METAFIELDS_MAPPING m LEFT JOIN DESIGN_SALES b ON b.CATEGORY = m.CATEGORY AND b.STATE = m.STATE AND b.DESIGN = m.DESIGN LEFT JOIN SLEEVE_SALES e ON e.CATEGORY = m.CATEGORY AND e.STATE = m.STATE AND e.SLEEVE = m.SLEEVE WHERE m.CATEGORY = \'SHIRTS\' AND m.DESIGN IS NOT NULL AND m.SLEEVE IS NOT NULL GROUP BY m.STATE, m.DESIGN, m.SLEEVE UNION ALL SELECT \'T-SHIRTS\' AS CATEGORY, m.STATE, m.COLLAR, m.DESIGN, NULL AS FIT, NULL AS MATERIAL, NULL AS SLEEVE, NULL AS STYLE, (0.5 * COALESCE(MAX(a.collar_sales), 0)) + (0.5 * COALESCE(MAX(b.design_sales), 0)) AS RAW_SALES_PERC FROM METAFIELDS_MAPPING m LEFT JOIN COLLAR_SALES a ON a.CATEGORY = m.CATEGORY AND a.STATE = m.STATE AND a.COLLAR = m.COLLAR LEFT JOIN DESIGN_SALES b ON b.CATEGORY = m.CATEGORY AND b.STATE = m.STATE AND b.DESIGN = m.DESIGN WHERE m.CATEGORY = \'T-SHIRTS\' AND m.COLLAR IS NOT NULL AND m.DESIGN IS NOT NULL GROUP BY m.STATE, m.COLLAR, m.DESIGN UNION ALL SELECT m.CATEGORY, m.STATE, NULL AS COLLAR, NULL AS DESIGN, m.FIT, CASE WHEN m.CATEGORY = \'JEANS\' THEN m.MATERIAL ELSE NULL END AS MATERIAL, NULL AS SLEEVE, NULL AS STYLE, CASE WHEN m.CATEGORY = \'JEANS\' AND m.MATERIAL IS NOT NULL THEN (0.7 * COALESCE(MAX(c.fit_sales), 0)) + (0.3 * COALESCE(MAX(d.material_sales), 0)) ELSE COALESCE(MAX(c.fit_sales), 0) END AS RAW_SALES_PERC FROM METAFIELDS_MAPPING m LEFT JOIN FIT_SALES c ON c.CATEGORY = m.CATEGORY AND c.STATE = m.STATE AND c.FIT = m.FIT LEFT JOIN MATERIAL_SALES d ON d.CATEGORY = m.CATEGORY AND d.STATE = m.STATE AND d.MATERIAL = m.MATERIAL WHERE m.CATEGORY IN (\'JEANS\', \'TROUSERS\', \'CARGO PANTS\', \'JOGGERS & TRACKPANTS\', \'CHINOS\') AND m.MATERIAL IS NOT NULL GROUP BY m.CATEGORY, m.STATE, m.FIT, m.MATERIAL UNION ALL SELECT \'OVERSHIRT\' AS CATEGORY, m.STATE, NULL AS COLLAR, m.DESIGN, NULL AS FIT, NULL AS MATERIAL, NULL AS SLEEVE, NULL AS STYLE, COALESCE(MAX(b.design_sales), 0) AS RAW_SALES_PERC FROM METAFIELDS_MAPPING m LEFT JOIN DESIGN_SALES b ON b.CATEGORY = m.CATEGORY AND b.STATE = m.STATE AND b.DESIGN = m.DESIGN WHERE m.CATEGORY = \'OVERSHIRT\' AND m.DESIGN IS NOT NULL GROUP BY m.STATE, m.DESIGN UNION ALL SELECT \'SHORTS\' AS CATEGORY, m.STATE, NULL AS COLLAR, m.DESIGN AS DESIGN, NULL AS FIT, NULL AS MATERIAL, NULL AS SLEEVE, NULL AS STYLE, (1 * COALESCE(MAX(b.design_sales), 0)) AS RAW_SALES_PERC FROM METAFIELDS_MAPPING m LEFT JOIN DESIGN_SALES b ON b.CATEGORY = m.CATEGORY AND b.STATE = m.STATE AND b.DESIGN = m.DESIGN LEFT JOIN FIT_SALES c ON c.CATEGORY = m.CATEGORY AND c.STATE = m.STATE AND c.FIT = m.FIT WHERE m.CATEGORY = \'SHORTS\' AND m.DESIGN IS NOT NULL AND m.FIT IS NOT NULL GROUP BY m.STATE, m.DESIGN UNION ALL SELECT m.CATEGORY, m.STATE, m.COLLAR, m.DESIGN, m.FIT, m.MATERIAL, m.SLEEVE, m.STYLE, (0.2 * COALESCE(MAX(a.collar_sales), 0)) + (0.2 * COALESCE(MAX(b.design_sales), 0)) + (0.2 * COALESCE(MAX(c.fit_sales), 0)) + (0.2 * COALESCE(MAX(d.material_sales), 0)) + (0.2 * COALESCE(MAX(e.sleeve_sales), 0)) AS RAW_SALES_PERC FROM METAFIELDS_MAPPING m LEFT JOIN COLLAR_SALES a ON a.CATEGORY = m.CATEGORY AND a.STATE = m.STATE AND a.COLLAR = m.COLLAR LEFT JOIN DESIGN_SALES b ON b.CATEGORY = m.CATEGORY AND b.STATE = m.STATE AND b.DESIGN = m.DESIGN LEFT JOIN FIT_SALES c ON c.CATEGORY = m.CATEGORY AND c.STATE = m.STATE AND c.FIT = m.FIT LEFT JOIN MATERIAL_SALES d ON d.CATEGORY = m.CATEGORY AND d.STATE = m.STATE AND d.MATERIAL = m.MATERIAL LEFT JOIN SLEEVE_SALES e ON e.CATEGORY = m.CATEGORY AND e.STATE = m.STATE AND e.SLEEVE = m.SLEEVE WHERE m.CATEGORY NOT IN (\'SHIRTS\', \'T-SHIRTS\', \'JEANS\', \'TROUSERS\', \'CARGO PANTS\', \'JOGGERS & TRACKPANTS\', \'CHINOS\', \'OVERSHIRT\', \'SHORTS\') GROUP BY m.CATEGORY, m.STATE, m.COLLAR, m.DESIGN, m.FIT, m.MATERIAL, m.SLEEVE, m.STYLE ), normalized_sales AS ( SELECT csm.*, SUM(csm.RAW_SALES_PERC) OVER (PARTITION BY csm.STATE, csm.CATEGORY) AS TOTAL_SALES_PERC FROM category_specific_metafields csm ), final_data AS ( SELECT STATE, CATEGORY, COLLAR, DESIGN, FIT, MATERIAL, SLEEVE, STYLE, CASE WHEN TOTAL_SALES_PERC > 0 THEN RAW_SALES_PERC / TOTAL_SALES_PERC ELSE 0 END AS SALES_PERC, 100 AS BRANCH_CODE FROM normalized_sales WHERE RAW_SALES_PERC > 0 ), sku_matching AS ( SELECT a.*, b.SKU_GROUP FROM METAFIELDS_DATA b LEFT JOIN final_data a ON UPPER(a.CATEGORY) = UPPER(b.CATEGORY) AND ( (UPPER(a.CATEGORY) = \'SHIRTS\' AND UPPER(a.DESIGN) = UPPER(b.DESIGNS) AND UPPER(a.SLEEVE) = UPPER(b.SLEEVE_TYPE)) OR (UPPER(a.CATEGORY) IN (\'T-SHIRTS\', \'OVERSHIRT\') AND UPPER(a.COLLAR) = UPPER(b.COLLAR_NEW) AND UPPER(a.DESIGN) = UPPER(b.DESIGNS)) OR (UPPER(a.CATEGORY) IN (\'JEANS\', \'TROUSERS\', \'CARGO PANTS\', \'JOGGERS\', \'TRACKPANTS\', \'CHINOS\') AND UPPER(a.FIT) = UPPER(b.FIT)) OR (UPPER(a.CATEGORY) = \'SHORTS\' AND UPPER(a.DESIGN) = UPPER(b.DESIGNS) AND UPPER(a.FIT) = UPPER(b.FIT)) OR (UPPER(a.CATEGORY) NOT IN (\'SHIRTS\', \'T-SHIRTS\', \'OVERSHIRT\', \'JEANS\', \'TROUSERS\', \'CARGO PANTS\', \'JOGGERS\', \'TRACKPANTS\', \'CHINOS\', \'SHORTS\') AND (COALESCE(NULLIF(UPPER(a.COLLAR), \'\'), UPPER(b.COLLAR_NEW)) = UPPER(b.COLLAR_NEW) OR a.COLLAR IS NULL) AND (COALESCE(NULLIF(UPPER(a.DESIGN), \'\'), UPPER(b.DESIGNS)) = UPPER(b.DESIGNS) OR a.DESIGN IS NULL) AND (COALESCE(NULLIF(UPPER(a.FIT), \'\'), UPPER(b.FIT)) = UPPER(b.FIT) OR a.FIT IS NULL) AND (COALESCE(NULLIF(UPPER(a.MATERIAL), \'\'), UPPER(b.MATERIAL)) = UPPER(b.MATERIAL) OR a.MATERIAL IS NULL) AND (COALESCE(NULLIF(UPPER(a.SLEEVE), \'\'), UPPER(b.SLEEVE_TYPE)) = UPPER(b.SLEEVE_TYPE) OR a.SLEEVE IS NULL) AND (COALESCE(NULLIF(UPPER(a.STYLE), \'\'), UPPER(b.STYLE)) = UPPER(b.STYLE) OR a.STYLE IS NULL)) ) ), class_mapping AS ( SELECT a.*, b.SKU_CLASS FROM SKU_MATCHING a JOIN snitch_db.maplemonk.CATEGORY_JOURNEY b ON UPPER(a.SKU_GROUP) = UPPER(b.SKU_GROUP) ), qty_data AS ( SELECT a.*, COALESCE(b.BASE_STOCK, 0) AS BASE, ROUND(SALES_PERC * BASE) AS QTY FROM final_data a JOIN google_sheet_nso_base_stock b ON UPPER(a.CATEGORY) = UPPER(b.CATEGORY) AND UPPER(a.STATE) = UPPER(b.STATE) ) select * from qty_data;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            